package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.relatorio.RelatorioContaPagarRepository; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Service public class RelatorioContaPagarApplicationService { private final RelatorioContaPagarRepository repo; private final SegurancaOrganizacaoService seguranca; public RelatorioContaPagarApplicationService(RelatorioContaPagarRepository r,SegurancaOrganizacaoService s){repo=r;seguranca=s;}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioContaPagarItem> pesquisar(RelatorioContaPagarFiltro f){validar(f);var p=repo.pesquisar(f.organizacaoUuid(),f.vencimentoInicio(),f.vencimentoFim(),f.fornecedorUuid(),status(f),f.somenteVencidas(),PageRequest.of(pagina(f),tamanho(f)));var itens=p.getContent().stream().map(x->new RelatorioContaPagarItem(x.getUuid(),x.getVencimento(),x.getFornecedorOrigem(),x.getDescricao(),x.getStatus(),nvl(x.getValorTotal()),nvl(x.getValorPago()),nvl(x.getSaldo()),Boolean.TRUE.equals(x.getVencida()),Boolean.TRUE.equals(x.getRepasse()))).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),p.getTotalElements(),p.getTotalPages(),"vencimento","asc");}
 @Transactional(readOnly=true) public RelatorioContaPagarResumo resumo(RelatorioContaPagarFiltro f){validar(f);var r=repo.resumo(f.organizacaoUuid(),f.vencimentoInicio(),f.vencimentoFim(),f.fornecedorUuid(),status(f),f.somenteVencidas());return new RelatorioContaPagarResumo(nvl(r.getValorTotal()),nvl(r.getValorPago()),nvl(r.getSaldoAPagar()));}
 private void validar(RelatorioContaPagarFiltro f){if(f.organizacaoUuid()==null)throw new IllegalArgumentException("Organização é obrigatória");if(f.vencimentoInicio()!=null&&f.vencimentoFim()!=null&&f.vencimentoFim().isBefore(f.vencimentoInicio()))throw new IllegalArgumentException("Vencimento final não pode ser anterior ao inicial");seguranca.validarAcesso(f.organizacaoUuid());} private String status(RelatorioContaPagarFiltro f){return f.status()==null?null:f.status().name();} private int pagina(RelatorioContaPagarFiltro f){return Math.max(0,f.pagina());} private int tamanho(RelatorioContaPagarFiltro f){return Math.max(10,Math.min(100,f.tamanho()));} private BigDecimal nvl(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
}
